def transform(grid):
    h, w = len(grid), len(grid[0])

    def get_lines(horizontal):
        if horizontal:
            return [row[:] for row in grid]
        return [[grid[r][c] for r in range(h)] for c in range(w)]

    def has_repeat(line):
        return any(line[i] != 0 and line[j] == line[i]
                   for i in range(len(line)) for j in range(i + 1, len(line)))

    # The repeated marks in these puzzles establish a single principal direction.
    horizontal_score = sum(has_repeat(line) for line in get_lines(True))
    vertical_score = sum(has_repeat(line) for line in get_lines(False))
    horizontal = horizontal_score >= vertical_score

    lines = get_lines(horizontal)
    processed = []

    for line in lines:
        n = len(line)
        pairs = []
        for i in range(n):
            if line[i] == 0:
                continue
            for j in range(i + 1, n):
                if line[j] == line[i]:
                    pairs.append((j - i, i, j, line[i]))

        if not pairs:
            processed.append(line)
            continue

        # Use the closest repeated marks to establish the repetition spacing.
        d = min(p[0] for p in pairs)
        seeds = [p for p in pairs if p[0] == d]
        result = line[:]

        for _, i, j, color in seeds:
            residue = i % d
            positions = list(range(residue, n, d))
            occupied = [p for p in positions if line[p] != 0]
            if not occupied:
                continue

            distinct = [p for p in occupied if line[p] != color]
            if distinct:
                fill_color = line[distinct[-1]]
                limit = max(occupied)
            else:
                fill_color = color
                limit = n - 1

            for p in positions:
                if p <= limit:
                    result[p] = fill_color

        processed.append(result)

    out = [row[:] for row in grid]
    if horizontal:
        out = processed
    else:
        for c, line in enumerate(processed):
            for r, value in enumerate(line):
                out[r][c] = value
    return out
